from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    mark = max((v for v in counts if v != bg), key=lambda v: counts[v])
    out = [row[:] for row in grid]
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == mark]
    if not points:
        return out

    minr = min(r for r, c in points)
    maxr = max(r for r, c in points)
    minc = min(c for r, c in points)
    maxc = max(c for r, c in points)

    for r in range(h):
        cols = [c for rr, c in points if rr == r]
        if len(cols) >= 3:
            for c in range(minc, maxc + 1):
                if out[r][c] == bg:
                    out[r][c] = 2

    for c in (minc, maxc):
        rows = [r for r, cc in points if cc == c]
        if len(rows) >= 2:
            for r in range(minr, maxr + 1):
                if out[r][c] == bg:
                    out[r][c] = 2
    return out
